def to_en(html):
    for pre, en, end in PREFIX:
        assert html.count(pre) == 1, f"expected once, found {html.count(pre)}: {pre}"
        a = html.index(pre)
        html = html[:a] + en + html[html.index(end, a):]
    for bm, en in EXACT:
        assert bm in html, f"not found: {bm}"
        html = html.replace(bm, en)
    return html
